CREATE TABLE IF NOT EXISTS explainer_provider (id INT NOT NULL PRIMARY KEY, document TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS explainer_usage (user_id VARCHAR(64) NOT NULL, day VARCHAR(10) NOT NULL, count INT NOT NULL DEFAULT 0, active_until BIGINT NOT NULL DEFAULT 0, request_id VARCHAR(64) NOT NULL DEFAULT '', PRIMARY KEY(user_id,day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS explainer_tasks (id VARCHAR(64) NOT NULL PRIMARY KEY, user_id VARCHAR(64) NOT NULL, request_key VARCHAR(128) NOT NULL, state VARCHAR(32) NOT NULL, question TEXT NOT NULL, mode VARCHAR(32) NOT NULL, level VARCHAR(32) NOT NULL, result LONGTEXT NOT NULL DEFAULT '', error_code VARCHAR(100) NOT NULL DEFAULT '', reservation TEXT NOT NULL DEFAULT '', created_at VARCHAR(32) NOT NULL, updated_at VARCHAR(32) NOT NULL, UNIQUE KEY explainer_user_request(user_id,request_key), KEY explainer_state_updated(state,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
